1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Single source of truth for the owner-address normalization rule, applied whenever an owner is
7	 * created. A raw address is reduced to a canonical stored form: surrounding and repeated whitespace
8	 * collapsed to single spaces, upper-cased, and common street-type abbreviations expanded to their
9	 * full words ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
10	 *
11	 * <p>The same normalized form is what gets stored and returned, what the required-field check tests
12	 * for blankness, and what every address comparison uses — household duplicate detection and the
13	 * shared household id both reduce through {@link #normalize} (see {@link OwnerHousehold}).
14	 */
15	final class OwnerAddress {
16	
17	    private OwnerAddress() {
18	    }
19	
20	    /**
21	     * Reduces an address to its canonical form: trimmed, inner runs of whitespace collapsed to a
22	     * single space, upper-cased, with common abbreviations expanded token by token. A {@code null}
23	     * value yields an empty string.
24	     */
25	    static String normalize(String value) {
26	        if (value == null) {
27	            return "";
28	        }
29	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
30	        if (collapsed.isEmpty()) {
31	            return "";
32	        }
33	        String[] tokens = collapsed.split(" ");
34	        for (int i = 0; i < tokens.length; i++) {
35	            switch (tokens[i]) {
36	                case "ST":
37	                    tokens[i] = "STREET";
38	                    break;
39	                case "RD":
40	                    tokens[i] = "ROAD";
41	                    break;
42	                case "AVE":
43	                    tokens[i] = "AVENUE";
44	                    break;
45	                default:
46	                    break;
47	            }
48	        }
49	        return String.join(" ", tokens);
50	    }
51	}
52

