package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's derived {@code identityKey} — the descriptive key returned
 * on an owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
 * where the telephone is reduced to E.164 through {@link OwnerTelephone#toE164} and the email
 * lower-cased through {@link OwnerEmail#normalize}; a missing email or household id contributes an
 * empty segment.
 *
 * <p>The {@code householdId} segment is the deterministic household id (see
 * {@link OwnerHousehold#householdId}), so two owners in the same household share that segment.
 * Duplicate detection itself keys off the household id directly (see {@link CheckOwnerIdentityUnique});
 * this class only derives the key the owner mapper returns.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * Builds the identity key from its three raw parts: the submitted/stored telephone (normalized
     * to E.164 here), the email (lower-cased here) and the already-derived household id. Any part
     * that is {@code null} or cannot normalize contributes an empty segment.
     */
    public static String identityKey(String telephone, String email, String householdId) {
        String normalizedTelephone = OwnerTelephone.toE164(telephone);
        String normalizedEmail = OwnerEmail.normalize(email);
        return (normalizedTelephone == null ? "" : normalizedTelephone) + "|"
                + (normalizedEmail == null ? "" : normalizedEmail) + "|"
                + (householdId == null ? "" : householdId);
    }

    /**
     * The identity key of an already-stored owner, read from its persisted fields. The single
     * {@code Owner}-to-key definition shared by {@link CheckOwnerIdentityUnique} and the owner
     * mapper, so the uniqueness check and the returned {@code identityKey} can never drift apart.
     */
    public static String identityKey(Owner owner) {
        return identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * The identity key a create request <em>would</em> produce. The household-id segment is derived
     * the same way {@link AssignOwnerHousehold} will later assign it: the stable
     * {@link OwnerHousehold#householdId} when the request opts in with {@code sharesHousehold: true},
     * otherwise empty.
     */
    static String forRequest(OwnerFieldsDto request) {
        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
                ? OwnerHousehold.householdId(request.getLastName(), request.getAddress())
                : "";
        return identityKey(request.getTelephone(), request.getEmail(), householdId);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags the owner as a <em>possible</em> (soft) duplicate of an existing owner.
 *
 * <p>Runs in the {@code POST /api/owners} pipeline after {@link FlagOwnerBulkSignup} and before
 * {@link SaveOwner}, so the new owner is not yet persisted and therefore not compared against
 * itself. By this point the request has already cleared {@link CheckOwnerIdentityUnique}, so it is
 * not a <em>hard</em> identity duplicate. A soft match is a weaker signal: an existing owner that
 * shares this owner's last name (case-insensitive) and postcode but carries a <em>different</em>
 * telephone. People who really are distinct but look alike — same family name, same postcode, new
 * phone — are still created, but flagged for review.
 *
 * <p>When such a match is found, {@code possibleDuplicate} is set to {@code true} and
 * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, so the
 * result is deterministic); otherwise {@code possibleDuplicate} is {@code false} and
 * {@code possibleDuplicateOf} stays null. A postcode is required on both sides for a match — an
 * owner with no postcode never soft-matches. The values are frozen at creation time and returned
 * unchanged on later reads.
 */
public class FlagOwnerPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();

        Integer matchId = null;
        if (postcode != null && !postcode.isBlank()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
                    continue;
                }
                if (equalsIgnoreCase(existing.getLastName(), lastName)
                        && postcode.equals(existing.getPostcode())
                        && !equalsIgnoreCase(existing.getTelephone(), telephone)) {
                    if (matchId == null || existing.getId() < matchId) {
                        matchId = existing.getId();
                    }
                }
            }
        }

        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

